#!/usr/bin/env python3
"""GENERATED by build/gen-realm-palettes.py — never hand-edit dev/model-qa/realm-palettes/*.json.

BEAUTY-WAVE.md VP1.5 step 1, r2 (docs/BEAUTY-WAVE.md §VP1.5 amended by the r2 laws in the
r2 brief — this REPLACES the r1 script, which was reverted for HUE MURDER + MAGENTA FLECKS).

r1's bug: the palette was k-means over the style-ref PNG ONLY. A realm's style ref is a
curated hero shot — it under-represents whole hue families that live in the actual sprite
corpus (r1: fantasy's green constrictor snake had nowhere green to quantize to, so it
rounded to brown). r2 fixes this at the source:

  PALETTE DERIVATION (r2 law 1): k-means over the UNION of:
    (a) the realm's style-ref PNG opaque pixels (identity/mood anchor), AND
    (b) a sampled histogram of the realm's own CUT-sprite corpus opaque pixels (coverage
        anchor — guarantees every hue family actually painted onto sprites gets weight).
  HUE-FAMILY COVERAGE: bucket ALL corpus pixels (not just palette output) into 12 30-degree
    hue families (by HSV hue; achromatic/near-gray pixels are excluded from the family
    census since hue is undefined). Any family holding >=2% of the corpus's chromatic
    pixel mass must own >=2 entries in the final palette — under-represented families get
    forced representative colors (family-mean chromatic pixel, plus a lighter/darker tint
    ramp partner) appended/swapped in.
  CHROMA-KEY FORBID: no palette entry may be within RGB-euclidean distance 60 of #FF00FF
    (magenta chroma-key) or #00FF00 (green-screen key) — the r1 MAGENTA FLECKS bug. Any
    k-means center that lands in a forbidden zone is nudged out (moved along the vector
    away from the offending key color until clear) rather than dropped, so hue coverage
    promises made above are never silently broken by this filter.

Output: dev/model-qa/realm-palettes/<realm>.json
  {realm, source, paletteSize (32-48), colors: ["#rrggbb", ...], outline,
   hueFamilyCoverage: {family: {pctOfCorpus, paletteEntries}}, corpusPixelsSampled}
"""
import colorsys
import json
import os
import re
import sys

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
STYLE_REF_DIR = os.path.join(REPO, "dev/model-qa/regen-v3/style-refs")
OUT_DIR = os.path.join(REPO, "dev/model-qa/realm-palettes")
INTERIOR_JS = os.path.join(REPO, "src/ui/theater-interior.js")
REGISTRY_JS = os.path.join(REPO, "data/sprite-registry.js")
SPRITES_DIR = os.path.join(REPO, "assets/sprites")

PALETTE_MIN, PALETTE_MAX = 32, 48
PALETTE_SIZE = 44  # within the 32-48 band, room to grow for forced hue-coverage entries

OUTLINE_DEFAULTS = {
    "fantasy": "selective-dark-umber",
    "gloom": "full-near-black",
    "chrome": "none",
}

REALMS = ["fantasy", "gloom", "chrome", "ash", "bright-kingdom", "cosmic", "frontier",
          "high-seas", "lost-world", "noir", "suburb", "theater", "pc"]

STYLE_REF_ALIAS = {"pc": "fantasy"}  # pc has no ref of its own — logged as kit-fallback

FORBID_KEYS = [(255, 0, 255), (0, 255, 0)]  # magenta chroma-key, green-screen key
FORBID_DIST = 60.0

N_HUE_FAMILIES = 12
# The r2 law sets a FLOOR (any family >=2% must own >=2 entries). Eyes-gate finding on
# the first r2 run: fantasy's greens pool at only 0.3-1.7% of the whole corpus (browns
# dominate), so the 2% floor left ZERO green entries and a green snake still went tan —
# the exact r1 hue-murder class. Coverage therefore extends DOWN to 0.5% families
# (stricter than the law's floor, which the law permits); at the 48-entry cap the forced
# entries swap out the most-overrepresented family's duplicates, so majority ramps
# barely thin while minority hues survive.
HUE_FAMILY_MIN_PCT = 0.005  # 0.5%
HUE_FAMILY_MIN_ENTRIES = 2
ACHROMATIC_SAT_FLOOR = 0.12  # below this HSV saturation, a pixel has no reliable hue family


def load_kit_colors():
    """Grep realmId -> [floorColor, wallColor, trimColor] out of INTERIOR_TILE_KITS."""
    src = open(INTERIOR_JS, "r", encoding="utf-8").read()
    m = re.search(r"const INTERIOR_TILE_KITS = Object\.freeze\(\{(.*?)\n\}\);", src, re.S)
    body = m.group(1) if m else ""
    kits = {}
    for block_m in re.finditer(r'realmId:\s*"([a-z-]+)".*?(?=realmId:|\Z)', body, re.S):
        block = block_m.group(0)
        realm = block_m.group(1)
        colors = re.findall(r'(?:floorColor|wallColor|trimColor):\s*"(#[0-9a-fA-F]{6})"', block)
        if colors:
            kits[realm] = colors
    return kits


def load_registry_slugs_by_realm():
    src = open(REGISTRY_JS, "r", encoding="utf-8").read()
    by_realm = {}
    for slug, body in re.findall(r'"(spr-[a-z0-9-]+)":\s*\{([^}]*)\}', src):
        if 'status:"cut"' not in body:
            continue
        m_realm = re.search(r'realm:"([a-z-]+)"', body)
        if not m_realm:
            continue
        by_realm.setdefault(m_realm.group(1), []).append(slug)
    return by_realm


def hex_to_rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def rgb_to_hex(rgb):
    return "#%02x%02x%02x" % tuple(max(0, min(255, int(round(c)))) for c in rgb)


def dist(a, b):
    return ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2) ** 0.5


def nudge_out_of_forbidden(rgb):
    """If rgb is within FORBID_DIST of a chroma-key color, push it away along the
    vector from the key to rgb until clear (never drop — preserves hue coverage)."""
    for key in FORBID_KEYS:
        d = dist(rgb, key)
        if d < FORBID_DIST:
            if d < 1e-6:
                # degenerate: rgb == key exactly; nudge toward mid-gray as an escape vector
                vec = (0.5 - key[0] / 255.0, 0.5 - key[1] / 255.0, 0.5 - key[2] / 255.0)
                vlen = max(1e-6, (vec[0] ** 2 + vec[1] ** 2 + vec[2] ** 2) ** 0.5)
                vec = tuple(v / vlen for v in vec)
            else:
                vec = tuple((rgb[i] - key[i]) / d for i in range(3))
            needed = FORBID_DIST - d + 1.0
            rgb = tuple(max(0, min(255, rgb[i] + vec[i] * needed)) for i in range(3))
    return rgb


def kmeans(pixels, k, iters=12, seed=17):
    import random
    rng = random.Random(seed)
    if len(pixels) <= k:
        return list(pixels)
    centers = [pixels[i] for i in rng.sample(range(len(pixels)), k)]
    for _ in range(iters):
        buckets = [[] for _ in range(k)]
        for p in pixels:
            best, bd = 0, None
            for i, c in enumerate(centers):
                d = (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2 + (p[2] - c[2]) ** 2
                if bd is None or d < bd:
                    bd, best = d, i
            buckets[best].append(p)
        new_centers = []
        for i, b in enumerate(buckets):
            if b:
                n = len(b)
                new_centers.append((sum(p[0] for p in b) / n,
                                     sum(p[1] for p in b) / n,
                                     sum(p[2] for p in b) / n))
            else:
                new_centers.append(centers[i])
        if new_centers == centers:
            break
        centers = new_centers
    return centers


def sample_png_pixels(path, max_samples):
    from PIL import Image
    im = Image.open(path).convert("RGBA")
    px = im.load()
    w, h = im.size
    pixels = []
    if w * h == 0:
        return pixels
    step = max(1, int(((w * h) / max_samples) ** 0.5)) if max_samples else 1
    for y in range(0, h, step):
        for x in range(0, w, step):
            r, g, b, a = px[x, y]
            if a < 200:
                continue
            # skip the flat magenta/green chroma-key background if present in source art
            if r > 200 and g < 60 and b > 200:
                continue
            if g > 200 and r < 60 and b < 60:
                continue
            pixels.append((r, g, b))
    return pixels


def sample_corpus_pixels(realm, slugs, per_sprite_samples=120, sprite_cap=200):
    """Sampled histogram of the realm's own cut-sprite corpus opaque pixels."""
    import random
    rng = random.Random(7)
    chosen = list(slugs)
    if len(chosen) > sprite_cap:
        rng.shuffle(chosen)
        chosen = chosen[:sprite_cap]
    pixels = []
    for slug in chosen:
        path = os.path.join(SPRITES_DIR, slug + ".png")
        if not os.path.exists(path):
            continue
        pixels.extend(sample_png_pixels(path, per_sprite_samples))
    return pixels


def hue_family_of(rgb):
    r, g, b = (c / 255.0 for c in rgb)
    hh, s, v = colorsys.rgb_to_hsv(r, g, b)
    if s < ACHROMATIC_SAT_FLOOR:
        return None
    fam = int(hh * N_HUE_FAMILIES) % N_HUE_FAMILIES
    return fam


def hue_family_census(pixels):
    """Return {family: {pct, pixels:[rgb,...]}} over the chromatic subset of pixels."""
    fam_pixels = {i: [] for i in range(N_HUE_FAMILIES)}
    chromatic_total = 0
    for p in pixels:
        fam = hue_family_of(p)
        if fam is None:
            continue
        fam_pixels[fam].append(p)
        chromatic_total += 1
    census = {}
    for fam, plist in fam_pixels.items():
        pct = (len(plist) / chromatic_total) if chromatic_total else 0.0
        census[fam] = {"pct": pct, "pixels": plist}
    return census


def entries_hue_family(colors_rgb):
    """Map each current palette entry rgb to its hue family (None if achromatic)."""
    return [hue_family_of(c) for c in colors_rgb]


def enforce_hue_coverage(colors_rgb, census):
    """Ensure any family with >=2% corpus mass owns >=2 palette entries. Appends/replaces
    the least-visually-distinct existing entries as needed (never drops hue coverage to
    stay under a hard cap — paletteSize may grow up to PALETTE_MAX)."""
    fam_counts = {}
    for c in colors_rgb:
        fam = hue_family_of(c)
        if fam is not None:
            fam_counts[fam] = fam_counts.get(fam, 0) + 1

    needs = []
    for fam, info in census.items():
        if info["pct"] >= HUE_FAMILY_MIN_PCT and fam_counts.get(fam, 0) < HUE_FAMILY_MIN_ENTRIES:
            needs.append((fam, info))

    for fam, info in needs:
        plist = info["pixels"]
        if not plist:
            continue
        # representative color = family pixel mean; the partner varies VALUE ONLY in HSV
        # space (never lightness-toward-white in RGB, which desaturates and can knock the
        # partner into a DIFFERENT/achromatic hue family — the bug this fixes) so both
        # entries are guaranteed to land back in the same family after nudging.
        mean = tuple(sum(p[i] for p in plist) / len(plist) for i in range(3))
        hh, s, v = colorsys.rgb_to_hsv(*(c / 255.0 for c in mean))
        v_partner = v * 0.6 if v > 0.5 else min(1.0, v * 1.4 + 0.1)
        partner = tuple(c * 255.0 for c in colorsys.hsv_to_rgb(hh, s, v_partner))

        candidates = [mean, partner]
        added_this_family = 0
        have = fam_counts.get(fam, 0)
        need_n = max(0, HUE_FAMILY_MIN_ENTRIES - have)
        for cand in candidates:
            if added_this_family >= need_n:
                break
            add = nudge_out_of_forbidden(cand)
            # verify the nudge didn't knock it out of the target family; if so, try the
            # un-nudged candidate scaled toward mid-value instead (still same hue/sat)
            if hue_family_of(add) != fam:
                add = cand  # not within a forbidden zone in the first place typically;
                # nudge only triggers near chroma keys, and this family's mean is a real
                # corpus color far from magenta/green-screen in the overwhelming case
            if len(colors_rgb) < PALETTE_MAX:
                colors_rgb.append(add)
            else:
                fam_of_all = [hue_family_of(c) for c in colors_rgb]
                worst_fam = max(set(f for f in fam_of_all if f is not None),
                                key=lambda f: fam_of_all.count(f))
                idx = fam_of_all.index(worst_fam)
                colors_rgb[idx] = add
            fam_counts[fam] = fam_counts.get(fam, 0) + 1
            added_this_family += 1
    return colors_rgb


def build_realm_palette(realm, kit_colors, registry_by_realm):
    ref_realm = STYLE_REF_ALIAS.get(realm, realm)
    ref_path = os.path.join(STYLE_REF_DIR, f"{ref_realm}-style-ref.png")
    kit = kit_colors.get(realm, kit_colors.get(ref_realm, []))
    fallback_used = []
    source = "style-ref+corpus"

    style_pixels = []
    if os.path.exists(ref_path):
        style_pixels = sample_png_pixels(ref_path, 20000)
        if not style_pixels:
            fallback_used.append("style-ref had no usable opaque pixels")
    else:
        fallback_used.append(f"no style-ref PNG at {os.path.relpath(ref_path, REPO)}")
    if ref_realm != realm:
        source = "style-ref+corpus(style borrowed:%s)" % ref_realm

    corpus_slugs = registry_by_realm.get(realm, [])
    corpus_pixels = sample_corpus_pixels(realm, corpus_slugs) if corpus_slugs else []
    if not corpus_slugs:
        fallback_used.append("no cut sprites in registry for this realm yet — style-ref only")

    union_pixels = style_pixels + corpus_pixels
    if not union_pixels:
        source = "kit-fallback"

    if union_pixels:
        centers = kmeans(union_pixels, min(PALETTE_SIZE, max(4, len(union_pixels))))
        colors_rgb = [tuple(c) for c in centers]
    else:
        base = [hex_to_rgb(c) for c in kit] or [(128, 128, 128)]
        colors_rgb = list(base)
        while len(colors_rgb) < PALETTE_SIZE:
            a = base[len(colors_rgb) % len(base)]
            b = base[(len(colors_rgb) + 1) % len(base)]
            colors_rgb.append(tuple(a[i] * 0.5 + b[i] * 0.5 for i in range(3)))

    # chroma-key forbid — nudge every entry clear of magenta/green keys
    colors_rgb = [nudge_out_of_forbidden(c) for c in colors_rgb]

    # hue-family coverage law, censused over the corpus pixels actually sampled (the
    # style-ref alone is not the corpus — the whole point of r2)
    census_source = corpus_pixels if corpus_pixels else union_pixels
    census = hue_family_census(census_source)
    # run twice: the first pass's additions can occasionally land off-family after a
    # forbidden-zone nudge (rare), so a second pass tops up anything still short.
    colors_rgb = enforce_hue_coverage(colors_rgb, census)
    colors_rgb = enforce_hue_coverage(colors_rgb, census)
    colors_rgb = [nudge_out_of_forbidden(c) for c in colors_rgb]

    # fold in kit colors verbatim (architecture/sprite hue agreement), forbid-checked too
    colors_hex = [rgb_to_hex(c) for c in colors_rgb]
    for c in kit:
        c_checked = rgb_to_hex(nudge_out_of_forbidden(hex_to_rgb(c)))
        if c_checked not in colors_hex and len(colors_hex) < PALETTE_MAX:
            colors_hex.append(c_checked)

    colors_hex = colors_hex[:PALETTE_MAX]
    if len(colors_hex) < PALETTE_MIN:
        # pad by re-adding forced hue-family reps if we somehow fell under the floor
        fallback_used.append(f"palette below floor ({len(colors_hex)}<{PALETTE_MIN}) — "
                              f"padded with kit interpolation")
        base = [hex_to_rgb(c) for c in colors_hex] or [(128, 128, 128)]
        i = 0
        while len(colors_hex) < PALETTE_MIN:
            a, b = base[i % len(base)], base[(i + 1) % len(base)]
            colors_hex.append(rgb_to_hex(tuple(a[j] * 0.5 + b[j] * 0.5 for j in range(3))))
            i += 1

    # final coverage report (informational — computed post-hoc from final entries)
    final_rgb = [hex_to_rgb(c) for c in colors_hex]
    fam_counts_final = {}
    for c in final_rgb:
        fam = hue_family_of(c)
        if fam is not None:
            fam_counts_final[fam] = fam_counts_final.get(fam, 0) + 1
    coverage_report = {
        str(fam): {"pctOfCorpus": round(info["pct"], 4),
                    "paletteEntries": fam_counts_final.get(fam, 0)}
        for fam, info in census.items() if info["pct"] > 0
    }

    return {
        "realm": realm,
        "source": source,
        "paletteSize": len(colors_hex),
        "colors": colors_hex,
        "outline": OUTLINE_DEFAULTS.get(realm, "tbd"),
        "hueFamilyCoverage": coverage_report,
        "corpusPixelsSampled": len(corpus_pixels),
        "fallbackNotes": fallback_used,
    }


def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    kit_colors = load_kit_colors()
    registry_by_realm = load_registry_slugs_by_realm()
    log_lines = []
    for realm in REALMS:
        data = build_realm_palette(realm, kit_colors, registry_by_realm)
        out_path = os.path.join(OUT_DIR, f"{realm}.json")
        payload = {
            "_generated_by": "build/gen-realm-palettes.py (r2) — never hand-edit",
            **data,
        }
        with open(out_path, "w", encoding="utf-8") as f:
            json.dump(payload, f, indent=2)
            f.write("\n")
        tag = "OK" if data["source"] != "kit-fallback" else "FALLBACK"
        print(f"{tag}: {realm} -> {data['source']} ({data['paletteSize']} colors, "
              f"{data['corpusPixelsSampled']} corpus px sampled)")
        if data["fallbackNotes"]:
            for n in data["fallbackNotes"]:
                log_lines.append(f"{realm}: {n}")
    if log_lines:
        print("\n--- FALLBACK/NOTES LOG ---")
        for l in log_lines:
            print(l)


if __name__ == "__main__":
    sys.exit(main())
